cat > src/orchestration/tools/registry.test.ts <<'E'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Berlin', unit: 'c'});

    expect(received).toEqual([{location: 'Berlin', unit: 'c'}]);
  });
});
